const b = $json.body || {};
const runId = String(b.run_id || '').trim();
if (!runId || !/^CMOS_E2E_[A-Za-z0-9_-]+$/.test(runId)) throw new Error('Valid CMOS_E2E run_id required');
const now = new Date().toISOString();
const alert = {
  schema_version: '1.0',
  alert_id: `SYSTEM_TEST:${runId}`,
  source: 'SYSTEM_TEST',
  source_event_id: runId,
  category: 'TEST',
  subtype: 'E2E_ACCEPTANCE',
  status: 'ACTIVE',
  event_action: 'NEW',
  title: 'City Manager OS acceptance test',
  message: `SYSTEM TEST - DO NOT DISPATCH. End-to-end routing validation ${runId}.`,
  priority: 2,
  county: 'Hudson',
  municipality: 'Weehawken',
  location: {label:'City Manager OS test harness',address:'',state:'NJ',zip:'',latitude:null,longitude:null,block:'',lot:'',qualifier:'',parcel_id:''},
  tags: ['system_test','e2e','acceptance'],
  click_url: '',
  source_url: '',
  observed_at: now,
  source_updated_at: now,
  received_at: now,
  expires_at: null,
  metadata: {run_id:runId, synthetic:true}
};
alert.search_text = [alert.source,alert.category,alert.subtype,alert.title,alert.message,...alert.tags].join(' ');
return [{json:alert}];
